(()=>{
const C=window.CM,$=s=>document.querySelector(s),ui={visitId:'LK-DEMO-001',tab:'overview',billId:'LK-DEMO-001',tableSearch:'',visitSearch:'',managerTab:'branch'};
const menus={manager:[['overview','◫','Tổng quan'],['manager','⚙','Cấu hình phòng khám'],['states','◌','Trạng thái UI']],reception:[['reception','▤','Tiếp nhận hôm nay'],['walkin','✚','Thêm bệnh nhân đến trực tiếp'],['queue','≡','Hàng đợi'],['states','◌','Trạng thái UI']],doctor:[['doctor','♧','Danh sách khám'],['encounter','▣','Hồ sơ lượt khám'],['states','◌','Trạng thái UI']],lab:[['lab','◈','Chỉ định & kết quả'],['states','◌','Trạng thái UI']],cashier:[['billing','◈','Hóa đơn & thu phí'],['states','◌','Trạng thái UI']],platform:[['platform','▧','Duyệt phòng khám'],['states','◌','Trạng thái UI']]};
const roleNames={manager:'Quản lý phòng khám',reception:'Lễ tân',doctor:'Bác sĩ',lab:'Nhân viên cận lâm sàng',cashier:'Thu ngân',platform:'Platform Ops'};
const routeRole={overview:'manager',manager:'manager',reception:'reception',walkin:'reception',queue:'reception',doctor:'doctor',encounter:'doctor',lab:'lab',billing:'cashier',platform:'platform'};
const route=()=>location.hash.slice(1)||'overview';
function shell(){let s=C.load(),r=route(),role=routeRole[r]||s.role;if(routeRole[r]&&s.role!==role){s.role=role;C.save(s)}$('#role-select').value=role;$('#context-branch').value=s.branch||'BR-001';$('#side-menu').innerHTML=`<div class="nav-section">${roleNames[role]}</div>${(menus[role]||[]).map(([id,ico,name])=>`<a class="side-link ${r===id?'active':''}" href="#${id}" ${r===id?'aria-current="page"':''} title="${name}"><span class="side-icon">${ico}</span><span>${name}</span></a>`).join('')}<div class="divider"></div><div class="role-note desktop-only">Đang dùng dữ liệu mẫu.<br>Vai trò và chi nhánh chỉ minh họa UX; quyền thật phải xác minh ở backend.</div><a class="side-link" href="public.html#home"><span class="side-icon">↗</span><span>Website bệnh nhân</span></a>`;let component={overview,manager,reception,walkin,queue,doctor,encounter,lab,billing,platform,states}[r]||overview;$('#main').innerHTML=component(s);}
const demo=()=>'<span class="sample-label">DỮ LIỆU GIẢ LẬP</span>';
const title=(h,p,extra='')=>C.header(h,p,extra||demo());
const filtered=(list,s)=>list.filter(v=>v.clinicId==='CL-001'&&v.branch===(s.branch||'BR-001'));
const tableHeads=(heads)=>`<thead><tr>${heads.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead>`;
const money=C.money;
function overview(s){const aps=filtered(s.appointments,s),vs=filtered(s.visits,s);let waiting=vs.filter(x=>x.status==='waiting').length;return `${title('Tổng quan vận hành','Cơ sở Trung tâm · Ngày mẫu 30/09/2026 · Chỉ số mô phỏng')}<div class="grid four"><div class="card kpi"><div class="stat-label">Lịch hẹn hôm nay</div><div class="stat-value">${aps.length}</div><span class="pill ok">Mã lịch riêng</span></div><div class="card kpi"><div class="stat-label">Chờ khám</div><div class="stat-value">${waiting}</div><span class="pill pending">Theo hàng đợi</span></div><div class="card kpi"><div class="stat-label">Lượt khám</div><div class="stat-value">${vs.length}</div><span class="pill progress">Encounter riêng</span></div><div class="card kpi"><div class="stat-label">Số tiền còn phải thu</div><div class="stat-value">${money(vs.reduce((a,v)=>a+Math.max(0,v.bill-v.paid),0))}</div><span class="pill">Không đồng nghĩa doanh thu</span></div></div><section class="section grid two"><div class="card"><div class="section-head"><div><h2>Tiếp nhận và điều phối</h2><p>Đặt lịch và bệnh nhân đến trực tiếp.</p></div></div><div class="record"><div><strong>Danh sách hôm nay</strong><div class="small muted">Khách chờ, check-in và xử lý ngoại lệ.</div></div><a class="btn secondary" href="#reception">Mở bàn tiếp nhận</a></div><div class="record"><div><strong>Hàng đợi khám</strong><div class="small muted">Phân biệt mã lượt khám và số thứ tự.</div></div><a class="btn secondary" href="#queue">Xem hàng đợi</a></div></div><div class="card"><h2>Thiết lập phòng khám</h2><p>Quản lý chi nhánh, nhân viên, dịch vụ, lịch và trạng thái công bố.</p><div class="notice">Mọi thông tin chưa duyệt chỉ xuất hiện trong workspace; website bệnh nhân chỉ hiển thị hồ sơ đã được công bố.</div><div class="button-row section"><a href="#manager" class="btn">Mở cấu hình</a><a href="#platform" class="btn secondary">Xem quy trình duyệt ↗</a></div></div></section><section class="section card"><h2>Quy trình vận hành hôm nay</h2><div class="grid four"><div><span class="pill">01</span><h3 style="margin-top:10px">Tiếp nhận</h3><p class="small">Đặt lịch hoặc walk-in</p></div><div><span class="pill">02</span><h3 style="margin-top:10px">Khám</h3><p class="small">Hồ sơ và chỉ định</p></div><div><span class="pill">03</span><h3 style="margin-top:10px">Thanh toán</h3><p class="small">Trực tiếp hoặc online</p></div><div><span class="pill">04</span><h3 style="margin-top:10px">Sau khám</h3><p class="small">Công bố tài liệu</p></div></div></section>`}
function manager(s){let t=ui.managerTab;let body='';if(t==='branch')body=`<h2>Cơ sở & chi nhánh</h2><div class="grid two"><div class="card flat"><span class="pill ok">Đang cấu hình</span><h3 style="margin:10px 0">Cơ sở Trung tâm</h3><p>Địa chỉ mẫu · Giờ mở cửa 07:30–17:30</p><div class="info-row"><span>◷</span><div>Thứ Hai – Thứ Bảy · 07:30–17:30</div></div></div><div class="card flat"><span class="pill">Chi nhánh</span><h3 style="margin:10px 0">Cơ sở phía Tây</h3><p>Trạng thái mẫu · Chưa đưa vào lịch đặt công khai.</p></div></div>`;if(t==='staff')body=`<h2>Nhân sự & phân quyền</h2><p>Quản lý gán vai trò theo từng cơ sở; một nhân viên có thể thuộc nhiều phòng khám.</p><div class="record"><div><strong>BS. Nguyễn Minh An (mẫu)</strong><div class="muted small">Bác sĩ · Cơ sở Trung tâm · Khám Nội tổng quát</div></div><span class="pill ok">Đã phân công</span></div><div class="record"><div><strong>Trần Như (mẫu)</strong><div class="muted small">Lễ tân · Cơ sở Trung tâm</div></div><span class="pill ok">Đang hoạt động</span></div><div class="notice warn section">Thao tác thu hồi quyền phải được kiểm chứng tại backend trên từng request; chuyển role trong prototype không phải phân quyền thật.</div>`;if(t==='price')body=`<h2>Danh mục dịch vụ & bảng giá</h2><div class="service-row"><div><strong>Khám Nội tổng quát</strong><div class="muted small">SKU-SV-DEMO-01 · Giá theo chi nhánh · V1 mẫu</div></div><div class="price">250.000 ₫</div></div><div class="service-row"><div><strong>Xét nghiệm cơ bản</strong><div class="muted small">Chỉ phát sinh khi bác sĩ có chỉ định</div></div><div class="price">200.000 ₫</div></div><div class="notice">Giá khi đặt lịch và giá khi phát sinh khoản thu cần snapshot/version riêng. Không chỉnh sửa bill quá khứ khi cập nhật bảng giá.</div>`;if(t==='publish')body=`<h2>Công bố Marketplace</h2><div class="summary-line"><span>Trạng thái hồ sơ (mô phỏng)</span><span class="pill ${s.platformClinicStatus==='approved'?'ok':'pending'}">${{submitted:'Đang chờ duyệt',approved:'Đã duyệt',needs_changes:'Cần bổ sung'}[s.platformClinicStatus]||s.platformClinicStatus}</span></div><p>Quản lý có thể xem trước, nhưng không thể tự quyết định trạng thái công khai nếu chưa qua bước duyệt của platform.</p><div class="mock-browser"><div class="mock-top">cliniccare.vn/clinic/an-binh-demo · Public preview</div><div class="mock-content"><h3>Phòng khám Đa khoa An Bình (mô phỏng)</h3><p>Nội tổng quát · Nhi khoa · Da liễu · Cơ sở Trung tâm</p><span class="pill ok">Bản xem trước</span></div></div><div class="button-row section"><a class="btn secondary" href="public.html#clinic">Xem website công khai ↗</a><a class="btn" href="#platform">Xem luồng Platform duyệt ↗</a></div>`;return `${title('Cấu hình phòng khám','Thông tin pháp lý, cơ sở, nhân sự và danh mục có trạng thái công bố riêng.')}<div class="card"><div class="tabs">${[['branch','Chi nhánh'],['staff','Nhân sự'],['price','Danh mục & giá'],['publish','Công bố']].map(([v,l])=>`<button class="tab ${t===v?'active':''}" data-action="manager-tab" data-tab="${v}">${l}</button>`).join('')}</div>${body}</div>`}
function reception(s){let list=filtered(s.appointments,s).filter(a=>!ui.tableSearch||[a.patient,a.id,a.patientCode].join(' ').toLowerCase().includes(ui.tableSearch.toLowerCase()));return `${title('Bàn tiếp nhận','Lịch hẹn và người đến trực tiếp được xử lý tại cùng một nơi.','<a href="#walkin" class="btn">+ Tiếp nhận không đặt lịch</a>')}<div class="grid four"><div class="card"><div class="stat-label">Lịch hẹn</div><div class="stat-value">${list.length}</div></div><div class="card"><div class="stat-label">Đã check-in</div><div class="stat-value">${list.filter(x=>x.status==='checked_in').length}</div></div><div class="card"><div class="stat-label">Chờ khám</div><div class="stat-value">${filtered(s.visits,s).filter(x=>x.status==='waiting').length}</div></div><div class="card"><div class="stat-label">Lượt trực tiếp</div><div class="stat-value">${filtered(s.visits,s).filter(x=>!x.appointmentId).length}</div></div></div><section class="section card"><div class="toolbar"><div><h2 style="margin:0">Lịch hẹn · 30/09/2026</h2><p style="margin:0">Tìm theo mã lịch, mã bệnh nhân hoặc họ tên.</p></div><input id="appointment-search" aria-label="Tìm lịch hẹn" placeholder="Tìm lịch / bệnh nhân" value="${C.esc(ui.tableSearch)}"></div><div class="table-wrap"><table class="data-table">${tableHeads(['Mã lịch','Bệnh nhân','Giờ & bác sĩ','Trạng thái','Thao tác'])}<tbody>${list.map(a=>`<tr><td data-label="Mã lịch"><strong>${a.id}</strong><small>Không phải mã lượt khám</small></td><td data-label="Bệnh nhân"><strong>${C.esc(a.patient)}</strong><small>Mã bệnh nhân: ${a.patientCode}</small></td><td data-label="Giờ & bác sĩ"><strong>${a.time} · ${C.date(a.date)}</strong><small>${C.esc(a.doctor)}</small></td><td data-label="Trạng thái">${C.badge(a.status)}</td><td data-label="Thao tác">${a.status==='confirmed'?`<button class="btn sm" data-action="checkin" data-id="${a.id}">Check-in</button>`:a.status==='checked_in'?`<a class="btn sm secondary" href="#queue">Xem hàng đợi</a>`:'<span class="small muted">Không có thao tác</span>'}</td></tr>`).join('')||`<tr><td colspan="5">Không tìm thấy lịch hẹn. Có thể tiếp nhận walk-in.</td></tr>`}</tbody></table></div></section><div class="notice section">Bệnh nhân chưa đặt web vẫn được tiếp nhận qua <strong>Walk-in</strong>. Mã lịch hẹn không được ghép vào số thứ tự hoặc mã bệnh nhân.</div>`}
function walkin(s){return `${title('Tiếp nhận bệnh nhân đến trực tiếp','Tạo lượt khám không yêu cầu tài khoản web hoặc lịch hẹn.')}<div class="split"><form id="walkin-form" class="card"><h2>Thông tin hành chính tối thiểu</h2><div class="fields"><div><label for="walk-name">Họ tên người khám *</label><input id="walk-name" name="name" required maxlength="100" placeholder="Ví dụ: Lê Minh (mẫu)"></div><div><label for="walk-phone">Số liên hệ <span class="optional">(không bắt buộc trong demo)</span></label><input id="walk-phone" name="phone" inputmode="tel" placeholder="0900 000 003"></div><div><label for="walk-service">Dịch vụ *</label><select id="walk-service" name="service"><option>Khám Nội tổng quát</option><option>Khám Nhi</option></select></div><div><label for="walk-doctor">Bác sĩ *</label><select id="walk-doctor" name="doctor"><option>BS. Nguyễn Minh An (mẫu)</option></select></div></div><div class="notice warn section"><strong>Kiểm tra trùng bệnh nhân</strong><br>Trong hệ thống thật cần đối chiếu danh tính có xác minh, không tự gộp chỉ dựa trên trùng số điện thoại. Demo luôn tạo mã bệnh nhân mới.</div><div class="button-row section"><button type="submit" class="btn">Tạo lượt khám & xếp hàng</button><a href="#reception" class="btn secondary">Hủy thao tác</a></div></form><aside class="card"><h3>Quy trình</h3><ol class="timeline"><li>Xác minh thông tin hành chính</li><li>Kiểm tra/liên kết hồ sơ bệnh nhân đúng quyền</li><li>Chọn dịch vụ và bác sĩ</li><li>Tạo <strong>mã lượt khám</strong> và số thứ tự</li><li>Đưa vào hàng đợi bác sĩ</li></ol><div class="notice">Appointment và Encounter được quản lý riêng. Lượt walk-in không cần mã lịch hẹn.</div></aside></div>`}
function queue(s){let vs=filtered(s.visits,s);return `${title('Hàng đợi khám','Theo chi nhánh và ngày làm việc. Mã STT không phải mã bệnh nhân.','<a href="#walkin" class="btn secondary">+ Thêm walk-in</a>')}<div class="grid two"><section class="card"><div class="section-head"><div><h2>Đang chờ / đang khám</h2><p>${vs.length} lượt tại cơ sở đang chọn</p></div><span class="pill progress">Ngày mẫu 30/09</span></div>${vs.map(v=>`<div class="queue-card"><div class="queue-index">${v.queue.split('-').pop()}</div><div style="flex:1"><strong>${C.esc(v.patient)}</strong><div class="muted small">Số thứ tự: ${v.queue} · Lượt khám: ${v.id}</div><div class="muted small">Mã bệnh nhân: ${v.patientCode}</div>${C.badge(v.status)}</div><div class="button-row">${v.status==='waiting'?`<button class="btn sm" data-action="start-visit" data-id="${v.id}">Gọi lượt</button>`:''}<button class="btn sm secondary" data-action="open-visit" data-id="${v.id}">Mở</button></div></div>`).join('')||`<div class="empty"><h3>Chưa có lượt khám</h3><a class="btn" href="#walkin">Tiếp nhận walk-in</a></div>`}</section><aside class="card"><h2>Điều phối an toàn</h2><p>Nếu bệnh nhân đến muộn, bác sĩ vắng, hoặc cần chuyển chuyên khoa, yêu cầu lý do và nhật ký điều phối.</p><div class="notice warn">Không xóa lịch hoặc xóa thanh toán khi chuyển lượt. Các hành động thay đổi thực sự cần backend transaction và audit.</div><h3 class="section">Nhắc nhân viên</h3><ol class="timeline"><li>Kiểm tra đúng chi nhánh và ngày</li><li>Xác minh bệnh nhân trước khi gọi</li><li>Đổi trạng thái và ghi actor/time</li><li>Bác sĩ bắt đầu Encounter riêng</li></ol></aside></div>`}
function doctor(s){let vs=filtered(s.visits,s);return `${title('Danh sách khám của tôi','Chỉ lượt khám được phân công tại cơ sở đang chọn.')}<div class="grid three"><div class="card"><div class="stat-label">Chờ khám</div><div class="stat-value">${vs.filter(x=>x.status==='waiting').length}</div></div><div class="card"><div class="stat-label">Đang khám</div><div class="stat-value">${vs.filter(x=>x.status==='in_progress').length}</div></div><div class="card"><div class="stat-label">Chờ kết quả</div><div class="stat-value">${vs.filter(x=>x.status==='awaiting_results').length}</div></div></div><section class="section card"><h2>Hàng đợi được giao</h2>${vs.map(v=>`<div class="record"><div><span class="pill">Số thứ tự: ${v.queue}</span><h3 style="margin:9px 0">${C.esc(v.patient)}</h3><div class="small muted">Mã lượt khám: ${v.id} · Mã bệnh nhân: ${v.patientCode}</div><div style="margin-top:6px">${C.badge(v.status)} ${v.signed?'<span class="pill ok">Đã xác nhận bệnh án</span>':''}</div></div><button class="btn" data-action="open-visit" data-id="${v.id}">Mở lượt khám →</button></div>`).join('')||`<div class="empty"><h3>Không có lượt khám trong danh sách</h3><p>Chỉ các lượt được phân công mới được hiển thị.</p></div>`}</section>`}
function encounter(s){let v=s.visits.find(x=>x.id===ui.visitId)||filtered(s.visits,s)[0];if(!v)return `${title('Hồ sơ lượt khám','Chưa có lượt khám được phân công.')}<div class="empty">Không có dữ liệu mẫu. <a href="#doctor">Về danh sách</a></div>`;ui.visitId=v.id;let tabs=[['overview','Tổng quan'],['note','Bệnh án'],['orders','Chỉ định & kết quả'],['rx','Đơn thuốc & kết thúc'],['history','Lịch sử']];let content='';if(ui.tab==='overview')content=`<div class="grid two"><div><h3>Thông tin tiếp nhận</h3><div class="summary-line"><span>Nguồn</span><strong>${v.appointmentId?'Đặt lịch qua hệ thống':'Walk-in'}</strong></div><div class="summary-line"><span>Mã lượt khám</span><strong>${v.id}</strong></div><div class="summary-line"><span>Mã lịch hẹn</span><strong>${v.appointmentId||'Không có'}</strong></div><div class="summary-line"><span>Số thứ tự</span><strong>${v.queue}</strong></div></div><div><h3>Thông tin lâm sàng</h3><div class="notice warn">Cần xác minh dị ứng, tiền sử và sinh hiệu trước khi kết luận. Các thông tin này không có trong dữ liệu mẫu.</div><p class="small">Không suy diễn dữ liệu y khoa từ tài khoản hoặc lịch hẹn.</p></div></div><div class="button-row section"><button class="btn" data-action="enc-tab" data-tab="note">Mở bệnh án →</button></div>`;if(ui.tab==='note')content=`<form id="note-form"><h3>Phiếu khám ngoại trú · ${v.signed?'Chỉ đọc':'Bản nháp'}</h3>${v.signed?'<div class="notice success">Bệnh án đã xác nhận. Không được ghi đè; chỉnh sửa phải dùng phụ lục/addendum có lý do, tác giả và thời gian.</div>':'<div class="notice">Lưu nháp không đồng nghĩa xác nhận chuyên môn.</div>'}<div class="fields section"><div class="wide"><label for="note">Lý do khám, triệu chứng, tiền sử và khám lâm sàng *</label><textarea id="note" name="note" ${v.signed?'readonly':''} required placeholder="Chỉ nhập thông tin giả lập cho nguyên mẫu">${C.esc(v.note)}</textarea></div><div class="wide"><label for="diagnosis">Chẩn đoán/kết luận *</label><textarea id="diagnosis" name="diagnosis" ${v.signed?'readonly':''} required placeholder="Chẩn đoán mẫu (không dùng cho điều trị)">${C.esc(v.diagnosis)}</textarea></div></div><div class="button-row section">${v.signed?'<button type="button" class="btn secondary" data-action="addendum">Đề nghị tạo phụ lục</button>':'<button class="btn" type="submit">Lưu bản nháp</button>'}<button type="button" class="btn secondary" data-action="enc-tab" data-tab="orders">Sang chỉ định →</button></div></form>`;if(ui.tab==='orders')content=`<h3>Chỉ định và kết quả</h3><div class="notice">Chỉ định, kết quả và trạng thái bác sĩ đã xem là ba bước riêng. Kết quả không tự kết luận thay bác sĩ.</div>${v.order?`<div class="record section"><div><strong>${C.esc(v.order)}</strong><div class="small muted">${v.result?'Đã có kết quả mẫu: '+C.esc(v.result):'Đang chờ kết quả'}</div><div class="small">${v.reviewed?'<span class="pill ok">Bác sĩ đã xem</span>':'<span class="pill pending">Chưa review</span>'}</div></div><div class="button-row">${!v.result?'<a href="#lab" class="btn secondary sm">Nhập kết quả ↗</a>':!v.reviewed?`<button class="btn sm" data-action="review-result" data-id="${v.id}">Xác nhận đã xem</button>`:''}</div></div>`:`<div class="empty section"><h3>Chưa có chỉ định</h3><p>Chỉ thêm khi có quyết định lâm sàng hợp lệ.</p></div>`}${!v.order&&!v.signed?`<button class="btn section" data-action="add-order" data-id="${v.id}">+ Tạo chỉ định xét nghiệm mẫu</button>`:''}<div class="button-row section"><button class="btn secondary" data-action="enc-tab" data-tab="rx">Sang đơn thuốc →</button></div>`;if(ui.tab==='rx')content=`<form id="rx-form"><h3>Đơn thuốc & hướng dẫn</h3><div class="notice warn">Prototype chỉ thử luồng nhập và xác nhận, không đưa ra gợi ý thuốc hoặc liều điều trị.</div><label for="rx">Hướng dẫn điều trị / nội dung đơn mẫu *</label><textarea id="rx" name="rx" ${v.signed?'readonly':''} required placeholder="Ví dụ: Dặn dò giả lập, không phải chỉ định điều trị">${C.esc(v.prescription)}</textarea><p class="field-note">Biểu mẫu thuốc, trường bắt buộc và loại chữ ký cần được chuyên môn/pháp chế duyệt (OD-05).</p><div class="button-row">${!v.signed?`<button class="btn secondary" type="submit">Lưu nội dung nháp</button><button class="btn" type="button" data-action="sign-visit" data-id="${v.id}">Xem lại & xác nhận bệnh án</button>`:`<span class="pill ok">✓ Đã xác nhận bệnh án</span>${!v.released?`<button type="button" class="btn" data-action="release" data-id="${v.id}">Công bố tài liệu demo</button>`:'<span class="pill ok">Đã công bố lên Portal</span>'}`}</div></form>`;if(ui.tab==='history')content=`<h3>Timeline nghiệp vụ</h3><ol class="timeline"><li>Tạo lượt khám · ${v.id} · ${v.appointmentId?'Từ lịch hẹn':'Walk-in'}</li><li>Trạng thái hiện tại · ${C.status(v.status)[0]}</li>${v.order?'<li>Đã tạo chỉ định xét nghiệm mẫu</li>':''}${v.result?'<li>Nhân sự cận lâm sàng trả kết quả mẫu</li>':''}${v.reviewed?'<li>Bác sĩ đã review kết quả</li>':''}${v.signed?'<li>Đã xác nhận bệnh án · bản ghi khóa chỉnh sửa</li>':''}${v.released?'<li>Tài liệu được công bố đến portal mẫu</li>':''}</ol><div class="notice">Trong hệ thống thật, timeline lấy từ audit events có actor, thời điểm, lý do và phiên bản.</div>`;return `${title('Hồ sơ lượt khám','Bác sĩ phụ trách · Không đồng bộ trạng thái bệnh án với thanh toán.','<a class="btn secondary" href="#doctor">← Danh sách khám</a>')}<div class="patient-header"><div><span class="pill progress">${v.queue}</span><h2 style="margin:7px 0">${C.esc(v.patient)}</h2><div class="small muted">Mã bệnh nhân: ${v.patientCode} · Mã lượt khám: ${v.id} · Cơ sở Trung tâm</div></div><div>${C.badge(v.status)} ${v.signed?'<span class="pill ok">Hồ sơ đã xác nhận</span>':''}</div></div><div class="card"><div class="tabs" role="tablist">${tabs.map(([id,label])=>`<button role="tab" aria-selected="${ui.tab===id}" data-action="enc-tab" data-tab="${id}" class="tab ${ui.tab===id?'active':''}">${label}</button>`).join('')}</div>${content}</div>`}
function lab(s){let vs=filtered(s.visits,s).filter(v=>v.order);return `${title('Danh sách chỉ định','Chỉ nhìn thấy order được phân công, không truy cập toàn bộ bệnh án.')}<div class="card">${vs.map(v=>`<div class="record"><div><span class="pill progress">Mã lượt: ${v.id}</span><h3 style="margin:9px 0">${C.esc(v.order)}</h3><div class="small muted">Bệnh nhân: ${C.esc(v.patient)} · ${v.result?'Đã trả kết quả mẫu':'Đang chờ kết quả'}</div></div>${v.result?'<span class="pill ok">Đã có kết quả</span>':`<form class="button-row" data-form="lab-result" data-id="${v.id}"><label class="small" style="margin:0">Kết quả mẫu<input aria-label="Kết quả giả lập" name="result" required placeholder="Ví dụ: Hoàn tất mẫu"></label><button class="btn sm" type="submit">Trả kết quả demo</button></form>`}</div>`).join('')||`<div class="empty"><h3>Chưa có chỉ định chờ xử lý</h3><p>Bác sĩ cần tạo chỉ định trước.</p></div>`}</div>`}
function billing(s){let vs=filtered(s.visits,s),v=vs.find(x=>x.id===ui.billId)||vs[0];if(!v)return `${title('Thu ngân','Chưa có khoản thu.')}<div class="empty"><h3>Không có bill trong cơ sở</h3><a href="#reception" class="btn">Tạo lượt khám mẫu</a></div>`;ui.billId=v.id;let remaining=Math.max(0,v.bill-v.paid);return `${title('Thanh toán & đối soát','Khoản phí thực tế, số đã thu và số dư được hiển thị độc lập.')}<div class="grid three"><div class="card"><div class="stat-label">Phải thu · mẫu</div><div class="stat-value">${money(v.bill)}</div></div><div class="card"><div class="stat-label">Đã thu</div><div class="stat-value">${money(v.paid)}</div></div><div class="card"><div class="stat-label">Còn lại</div><div class="stat-value">${money(remaining)}</div></div></div><div class="split section"><section class="card"><h2>Khoản phí của lượt khám</h2><label for="bill-select">Chọn lượt khám</label><select id="bill-select">${vs.map(z=>`<option value="${z.id}" ${z.id===v.id?'selected':''}>${z.id} · ${C.esc(z.patient)}</option>`).join('')}</select><div class="service-row"><div><strong>Khám Nội tổng quát (snapshot)</strong><div class="small muted">Nguồn: Encounter · Dịch vụ mẫu</div></div><strong>${money(v.serviceFee||250000)}</strong></div>${v.order?`<div class="service-row"><div><strong>Xét nghiệm cơ bản (snapshot)</strong><div class="small muted">Nguồn: order mẫu · đã tạo chỉ định</div></div><strong>${money(200000)}</strong></div>`:''}<div class="summary-line"><span>Tổng khoản thu</span><strong>${money(v.bill)}</strong></div><div class="summary-line"><span>Đặt cọc</span><strong>0 ₫</strong></div><div class="summary-line"><span>Đã thu</span><strong>${money(v.paid)}</strong></div><hr><div class="summary-line"><strong>Còn lại</strong><strong class="money">${money(remaining)}</strong></div>${v.paymentLog.length?`<h3 class="section">Lịch sử thanh toán demo</h3>${v.paymentLog.map(p=>`<div class="summary-line"><span>${C.esc(p.method)} · ${C.esc(p.ref)}</span><strong>${money(p.amount)}</strong></div>`).join('')}`:''}</section><aside class="card"><h2>Thu tiền tại quầy</h2><p>Trực tiếp: tiền mặt, chuyển khoản/POS. Online cần xác minh từ Billing Service, không được đánh dấu trả tiền chỉ từ nút UI.</p><form id="payment-form"><label for="amount">Số tiền thu (₫)</label><input id="amount" type="number" name="amount" min="1" max="${remaining}" step="1000" value="${remaining}" required ${remaining===0?'disabled':''}><label for="method" style="margin-top:12px">Phương thức thu</label><select id="method" name="method"><option>Tiền mặt</option><option>Chuyển khoản tại quầy</option><option>POS</option></select><button type="submit" class="btn full section" ${remaining===0?'disabled':''}>Ghi nhận thu tại quầy (demo)</button></form><div class="divider"></div><h3>Trạng thái giao dịch online (demo)</h3><div class="notice">Tạo giao dịch mẫu không làm tăng số đã thu. Nút xác minh dưới đây chỉ là mô phỏng phản hồi có thẩm quyền, <strong>không thực hiện webhook hoặc thanh toán thật.</strong></div><div class="button-row section"><button class="btn sm secondary" data-action="online-pending" ${remaining===0?'disabled':''}>Tạo giao dịch chờ xác minh</button></div>${v.paymentLog.filter(p=>p.method.startsWith('Online')).map(p=>`<div class="record"><div><strong>${C.esc(p.ref)} · ${money(p.amount)}</strong><div class="small muted">${p.status==='paid'?'Đã xác minh (mô phỏng)':'Đang chờ xác minh — không tính vào số đã thu'}</div></div>${p.status==='pending'?`<button class="btn sm" data-action="verify-online" data-id="${p.ref}">Mô phỏng xác minh</button>`:'<span class="pill ok">Đã xác minh</span>'}</div>`).join('')}<div class="button-row section"><button class="btn secondary sm" data-action="refund">Quy trình hoàn tiền</button><button class="btn secondary sm" data-action="close-shift">Xem chốt ca</button></div></aside></div>`}
function platform(s){let status=s.platformClinicStatus;return `${title('Duyệt hồ sơ cơ sở','Console vận hành nền tảng, tách biệt khỏi quyền truy cập bệnh án.')}<div class="grid three"><div class="card"><div class="stat-label">Hồ sơ chờ xử lý</div><div class="stat-value">${status==='submitted'?1:0}</div></div><div class="card"><div class="stat-label">Cần bổ sung</div><div class="stat-value">${status==='needs_changes'?1:0}</div></div><div class="card"><div class="stat-label">Đã duyệt (demo)</div><div class="stat-value">${status==='approved'?1:0}</div></div></div><section class="section card"><h2>Yêu cầu đăng ký phòng khám</h2><div class="record"><div><span class="pill ${status==='approved'?'ok':'pending'}">${{submitted:'Chờ duyệt',needs_changes:'Cần bổ sung',approved:'Đã duyệt'}[status]}</span><h3 style="margin:8px 0">Phòng khám Đa khoa An Bình (mô phỏng)</h3><div class="small muted">Mã cơ sở: CL-001 · Hồ sơ và giấy phép mô phỏng, không dùng pháp lý</div></div><div class="button-row">${status!=='approved'?`<button class="btn" data-action="approve-clinic">Duyệt mẫu</button>`:''}<button class="btn secondary" data-action="request-changes">Yêu cầu bổ sung</button></div></div><div class="notice section">Duyệt ở đây chỉ thay đổi localStorage. Trong sản phẩm thật cần đối chiếu giấy phép/phạm vi hoạt động, người duyệt, lý do, audit và đồng bộ read model công khai. Platform Ops không tự có quyền xem hồ sơ bệnh án.</div></section>`}
function states(s){return `${title('Thư viện trạng thái','Trạng thái bắt buộc cho mọi nhóm màn hình.')}<div class="grid two"><div class="card"><span class="pill pending">Loading</span><h3>Đang tải lượt khám</h3><p>Giữ dữ liệu đã nhập khi tải lại và báo nguồn đang tải.</p></div><div class="card"><span class="pill danger">Permission denied</span><h3>Không có quyền truy cập trong cơ sở đang chọn</h3><p>Không hiển thị chi tiết bệnh án trong toast/log của UI.</p></div><div class="card"><span class="pill pending">Partial failure</span><h3>Lưu bản nháp thành công; gửi thông báo chưa xong</h3><p>Không làm giả trạng thái hoàn tất tất cả tác vụ.</p></div><div class="card"><span class="pill progress">Awaiting results</span><h3>Bác sĩ đang chờ kết quả</h3><p>Không tự động kết thúc encounter khi hết ca.</p></div><div class="card"><span class="pill danger">Conflict</span><h3>Khung giờ không còn</h3><p>Giữ dữ liệu bệnh nhân, cho chọn khung giờ khác.</p></div><div class="card"><span class="pill progress">Verification pending</span><h3>Giao dịch đang đối soát</h3><p>Không đánh dấu đã thanh toán khi chỉ nhận redirect.</p></div></div><div class="button-row section"><button class="btn secondary" data-action="reset">Đặt lại toàn bộ dữ liệu demo</button></div>`}
function act(e){let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id,s=C.load();if(a==='reset'){if(confirm('Đặt lại dữ liệu demo?')){C.reset();location.hash='overview';C.toast('Đã đặt lại dữ liệu giả lập.')}return}if(a==='manager-tab'){ui.managerTab=b.dataset.tab;shell();return}if(a==='checkin'){let ap=s.appointments.find(x=>x.id===id);if(!ap||ap.status!=='confirmed')return;ap.status='checked_in';let n=String(s.seq++).padStart(3,'0');s.visits.push({id:'LK-DEMO-'+n,appointmentId:ap.id,clinicId:ap.clinicId,patientCode:ap.patientCode,patient:ap.patient,branch:ap.branch,doctor:ap.doctor,time:ap.time,queue:'STT-'+n,status:'waiting',note:'',diagnosis:'',order:'',result:'',reviewed:false,prescription:'',signed:false,released:false,serviceFee:ap.fee||250000,bill:ap.fee||250000,paid:0,paymentLog:[],owned:!!ap.owned});C.save(s);C.toast('Đã check-in và tạo lượt khám riêng '+ 'LK-DEMO-'+n);shell();return}if(a==='open-visit'){ui.visitId=id;ui.tab='overview';location.hash='encounter';return}if(a==='start-visit'){let v=s.visits.find(x=>x.id===id);if(v&&v.status==='waiting'){v.status='in_progress';C.save(s);C.toast('Đã gọi lượt khám.');shell();}return}if(a==='enc-tab'){ui.tab=b.dataset.tab;shell();return}if(a==='add-order'){let v=s.visits.find(x=>x.id===id);if(v&&!v.order&&!v.signed){v.order='Xét nghiệm cơ bản (mẫu)';v.bill+=200000;v.status='awaiting_results';C.save(s);C.toast('Chỉ định mẫu đã tạo. Chờ nhân sự cận lâm sàng trả kết quả.');shell();}return}if(a==='review-result'){let v=s.visits.find(x=>x.id===id);if(v&&v.result){v.reviewed=true;v.status='in_progress';C.save(s);C.toast('Đã ghi nhận bác sĩ xem kết quả mẫu.');shell();}return}if(a==='sign-visit'){let v=s.visits.find(x=>x.id===id);if(!v||v.signed)return;if(!v.note.trim()||!v.diagnosis.trim()||!v.prescription.trim()){C.toast('Cần lưu bản nháp, kết luận và hướng dẫn trước khi xác nhận.','error');return}if(v.order&&(!v.result||!v.reviewed)){C.toast('Cần có kết quả và bác sĩ review chỉ định trước khi xác nhận.','error');return}if(confirm('Xác nhận bệnh án mô phỏng? Sau bước này biểu mẫu chuyển sang chỉ đọc; sửa phải dùng phụ lục. Đây không phải chữ ký điện tử hợp lệ.')){v.signed=true;v.status='clinically_completed';C.save(s);C.toast('Đã đánh dấu bệnh án xác nhận trong demo. Chưa công bố portal.');shell()}return}if(a==='release'){let v=s.visits.find(x=>x.id===id);if(v?.signed){v.released=true;C.save(s);C.toast('Đã công bố tài liệu mẫu lên Patient Portal.');shell()}return}if(a==='addendum'){C.toast('Phụ lục cần ghi lý do, tác giả, thời điểm và version. Chưa mô phỏng chỉnh sửa bản ký.');return}if(a==='online-pending'){let v=s.visits.find(x=>x.id===ui.billId);let remain=v.bill-v.paid-v.paymentLog.filter(p=>p.status==='pending').reduce((n,p)=>n+p.amount,0);if(remain<=0){C.toast('Không còn khoản tiền có thể tạo giao dịch chờ.','error');return}v.paymentLog.push({amount:remain,method:'Online · Cổng thanh toán mẫu',ref:'PM-DEMO-'+String(s.seq++).padStart(3,'0'),status:'pending'});C.save(s);C.toast('Đã tạo giao dịch chờ xác minh. Số đã thu không đổi.');shell();return}if(a==='verify-online'){let v=s.visits.find(x=>x.id===ui.billId),p=v?.paymentLog.find(x=>x.ref===id);if(p?.status==='pending'){let rem=v.bill-v.paid;if(p.amount>rem){C.toast('Số dư đã thay đổi; cần đối soát, không tự ghi đè.','error');return}p.status='paid';v.paid+=p.amount;C.save(s);C.toast('Mô phỏng xác minh giao dịch thành công; lần lặp không ghi nhận tiền thêm.');shell()}return}if(a==='refund'){alert('Luồng thiết kế: yêu cầu hoàn tiền → lý do + tham chiếu payment → phê duyệt theo quyền → gateway/ledger xác nhận → đối soát. Chính sách và bên trả tiền thuộc OD-01/03/08; prototype không hoàn tiền thật.');return}if(a==='close-shift'){alert('Chốt ca demo: đối chiếu tiền mặt + chuyển khoản tại quầy + giao dịch online đã xác thực - hoàn tiền. Phải báo chênh lệch và người xác nhận. Không tự chỉnh sửa ledger.');return}if(a==='approve-clinic'){s.platformClinicStatus='approved';C.save(s);C.toast('Đã duyệt trạng thái trong demo (không phải công bố thực tế).');shell();return}if(a==='request-changes'){let reason=prompt('Lý do yêu cầu bổ sung (mẫu):','Cần bổ sung thông tin giấy phép.');if(reason?.trim()){s.platformClinicStatus='needs_changes';C.save(s);C.toast('Đã ghi nhận trạng thái cần bổ sung trong demo.');shell()}return}}
function submit(e){const f=e.target;if(!['walkin-form','note-form','rx-form','payment-form'].includes(f.id)&&f.dataset.form!=='lab-result')return;e.preventDefault();let s=C.load(),d=new FormData(f);if(f.id==='walkin-form'){let name=String(d.get('name')||'').trim();if(!name){C.toast('Vui lòng nhập họ tên người khám.','error');return}let n=String(s.seq++).padStart(3,'0');s.visits.push({id:'LK-DEMO-'+n,appointmentId:null,clinicId:'CL-001',patientCode:'BN-DEMO-'+n,patient:name,branch:s.branch,doctor:String(d.get('doctor')),time:'walk-in',queue:'STT-'+n,status:'waiting',note:'',diagnosis:'',order:'',result:'',reviewed:false,prescription:'',signed:false,released:false,serviceFee:250000,bill:250000,paid:0,paymentLog:[],owned:false});C.save(s);C.toast(`Đã tạo LK-DEMO-${n}, số thứ tự STT-${n}; không tạo lịch hẹn.`);location.hash='queue';return;}if(f.id==='note-form'){let v=s.visits.find(x=>x.id===ui.visitId);if(v&&!v.signed){v.note=String(d.get('note')||'').trim();v.diagnosis=String(d.get('diagnosis')||'').trim();if(!v.note||!v.diagnosis){C.toast('Điền nội dung bệnh án và chẩn đoán trước khi lưu.','error');return}if(v.status==='waiting')v.status='in_progress';C.save(s);C.toast('Đã lưu bản nháp mô phỏng.');shell()}return}if(f.id==='rx-form'){let v=s.visits.find(x=>x.id===ui.visitId);if(v&&!v.signed){v.prescription=String(d.get('rx')||'').trim();C.save(s);C.toast('Đã lưu hướng dẫn/đơn mẫu.');shell()}return}if(f.dataset.form==='lab-result'){let v=s.visits.find(x=>x.id===f.dataset.id);if(v&&v.order&&!v.result){v.result=String(d.get('result')||'').trim();if(!v.result){C.toast('Nhập kết quả mẫu trước khi trả.','error');return}C.save(s);C.toast('Đã trả kết quả mẫu. Bác sĩ cần review.');shell()}return}if(f.id==='payment-form'){let v=s.visits.find(x=>x.id===ui.billId);let n=Number(d.get('amount'));let rem=v.bill-v.paid;if(!Number.isFinite(n)||n<=0||n>rem){C.toast('Số tiền phải dương và không vượt số dư.','error');return}v.paid+=n;v.paymentLog.push({amount:n,method:String(d.get('method')),ref:'PM-DEMO-'+String(s.seq++).padStart(3,'0'),status:'paid'});C.save(s);C.toast('Đã ghi nhận thanh toán tại quầy trong demo.');shell();return;}}
document.addEventListener('click',act);document.addEventListener('submit',submit);document.addEventListener('input',e=>{if(e.target.id==='appointment-search'){ui.tableSearch=e.target.value;let pos=e.target.selectionStart;shell();let i=$('#appointment-search');i.focus();i.setSelectionRange(pos,pos)}});document.addEventListener('change',e=>{let s=C.load();if(e.target.id==='role-select'){let r=e.target.value;s.role=r;C.save(s);location.hash=menus[r][0][0];shell()}if(e.target.id==='context-branch'){s.branch=e.target.value;C.save(s);shell();C.toast('Đã chuyển cơ sở mẫu. Hệ thống thật phải kiểm tra lại quyền và nạp dữ liệu đúng chi nhánh.')}if(e.target.id==='bill-select'){ui.billId=e.target.value;shell()}});window.addEventListener('hashchange',shell);window.addEventListener('demochange',shell);shell();
})();
